-- Insert Quiz Questions for Lesson: Plan Your Email Before Building

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'plan-your-email' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson plan-your-email not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is it important to answer ''Who is this email for?'' before writing?', 
    '["So you can charge them more money","To know which font size to use","So you can tailor the message to their specific situation and needs","To decide what time to send it"]'::jsonb,
    'So you can tailor the message to their specific situation and needs',
    'Knowing your audience helps you write relevant content that speaks to their specific situation, increasing the chances they''ll take action.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What happens if your email has too many ideas or calls-to-action?', 
    '["People will share it more often","People will do nothing because they are confused about what to do","It will automatically be split into multiple emails","The email will be marked as spam"]'::jsonb,
    'People will do nothing because they are confused about what to do',
    'When you give people too many options or messages, they experience decision paralysis and often take no action at all.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'When should you save an email as a reusable template?', 
    '["Only for welcome emails","When you will send the same type of email multiple times","Only for emails with images","Never - templates are not recommended"]'::jsonb,
    'When you will send the same type of email multiple times',
    'Save any email as a template if you''ll send similar messages repeatedly - follow-ups, thank-yous, reminders, resource deliveries, etc.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


