-- Insert Quiz Questions for Lesson: Create an Email Template

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-email-template' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-email-template not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Where do you go to create a new email template in LeadProspectrr?', 
    '["Contacts > Import","Marketing > Emails > Templates","Settings > Integrations","Dashboard > Reports"]'::jsonb,
    'Marketing > Emails > Templates',
    'Email templates are created in the Marketing section under Emails, then Templates.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is it important to use clear template names?', 
    '["It makes the email send faster","So you can easily find and identify the right template later","It improves email deliverability","It is required by LeadProspectrr"]'::jsonb,
    'So you can easily find and identify the right template later',
    'Clear names like ''Welcome - New Lead'' help you quickly find the right template when you need it, especially as your template library grows.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do before saving a new template?', 
    '["Delete all other templates","Send yourself a test email to check how it looks","Share it on social media","Print a physical copy"]'::jsonb,
    'Send yourself a test email to check how it looks',
    'Always send yourself a test email to preview formatting, check links, and see how it appears on both desktop and mobile before saving.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


