-- Insert Quiz Questions for Lesson: Write Effective Email Content

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'write-effective-email' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson write-effective-email not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the purpose of the subject line?', 
    '["To tell the full story of the email","To tell them why they should open the email","To include all your contact information","To make the email look longer"]'::jsonb,
    'To tell them why they should open the email',
    'The subject line''s job is to get the email opened. It should be clear, specific, and give the recipient a reason to open and read more.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'According to the golden rule, how many actions should one email contain?', 
    '["As many as possible","Three to five actions","One clear action","It depends on the email length"]'::jsonb,
    'One clear action',
    'One email, one message, one action. Multiple calls-to-action confuse readers and reduce the chance they''ll take any action at all.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should the first line of your email do?', 
    '["Include your company history","List all your services","Explain why they are receiving this email and set the context","Ask for a sale immediately"]'::jsonb,
    'Explain why they are receiving this email and set the context',
    'The first line sets context and reminds the recipient why they''re getting this email, making them more likely to continue reading.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


