-- Insert Quiz Questions for Lesson: Add Personalization to Emails

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'add-personalization' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson add-personalization not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the benefit of using personalization fields in emails?', 
    '["It makes the email send faster","It makes the email feel more human and relevant to the recipient","It reduces the email file size","It automatically translates the email"]'::jsonb,
    'It makes the email feel more human and relevant to the recipient',
    'Personalization fields like first name make emails feel individually written, increasing engagement and response rates.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What happens if a personalization field is broken or empty?', 
    '["The email sends normally with no issues","The email looks careless and unprofessional","The email is automatically deleted","The recipient cannot open the email"]'::jsonb,
    'The email looks careless and unprofessional',
    'Broken personalization fields show the raw code (like ''{{contact.first_name}}'') or blank spaces, making your email look sloppy and automated rather than personal.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Which personalization field is most commonly used and impactful?', 
    '["IP address","First name","Browser type","Email domain"]'::jsonb,
    'First name',
    'First name is the most common and impactful personalization field. Starting an email with ''Hi Sarah,'' feels much more personal than ''Hi there,'' or ''Dear Customer,''', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


