-- Insert Quiz Questions for Lesson: Review Before Sending

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'review-before-sending' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson review-before-sending not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why is it important to check if the email looks good on mobile?', 
    '["Mobile emails are more expensive to send","Most emails are opened on mobile devices","Desktop email is being discontinued","Mobile emails send faster"]'::jsonb,
    'Most emails are opened on mobile devices',
    'Over 60% of emails are opened on mobile devices. If your email doesn''t look good on a phone, most of your audience will have a poor experience.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do if you find a broken link during your review?', 
    '["Send it anyway - most people won''t click","Fix the link before sending","Remove all links from the email","Add more links to compensate"]'::jsonb,
    'Fix the link before sending',
    'Broken links destroy credibility and waste the opportunity. Always fix broken links before sending - the call-to-action is the whole point of the email.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How long should your review take?', 
    '["At least one hour","Five minutes is enough to catch most issues","No review is needed if you use templates","Reviews should be done by a committee"]'::jsonb,
    'Five minutes is enough to catch most issues',
    'A quick five-minute review using a checklist can catch most major issues and save you from embarrassing mistakes. It''s a small investment for much better results.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


