-- Insert Quiz Questions for Lesson: Understand Campaign Results

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'understand-campaign-results' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson understand-campaign-results not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What does a high open rate but low click rate indicate?', 
    '["Your subject line is ineffective","Your call-to-action or offer isn''t compelling enough","Your email is too short","You sent it at the wrong time of day"]'::jsonb,
    'Your call-to-action or offer isn''t compelling enough',
    'If people open but don''t click, your subject line worked (they opened) but your content or CTA didn''t motivate action.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you do if your open rate is low?', 
    '["Send the same email again immediately","Work on improving your subject line","Add more links to the email","Send to more people"]'::jsonb,
    'Work on improving your subject line',
    'Low open rates usually indicate the subject line isn''t compelling enough. Test different subject lines to see what resonates with your audience.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'How should you interpret results from a single email campaign?', 
    '["Judge it harshly if it doesn''t perform perfectly","Use it as one data point and look for patterns over time","Delete the email and never send campaigns again","Immediately change your entire business strategy"]'::jsonb,
    'Use it as one data point and look for patterns over time',
    'One email is a single data point. Look for patterns across multiple campaigns to understand what works for your specific audience.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;


