-- Insert Quiz Questions for Lesson: Create Your Follow-Up Template

DO $$
DECLARE
  v_module_id UUID;
  v_lesson_id UUID;
  v_quiz_id UUID;
BEGIN
  -- Get Module by week number
  SELECT id INTO v_module_id FROM public.training_modules WHERE week_number = 3 LIMIT 1;
  
  IF v_module_id IS NULL THEN
    RAISE NOTICE 'Module 3 not found';
    RETURN;
  END IF;

  -- Get the lesson ID
  SELECT id INTO v_lesson_id 
  FROM public.lessons 
  WHERE slug = 'create-followup-template' AND module_id = v_module_id;
  
  IF v_lesson_id IS NULL THEN
    RAISE NOTICE 'Lesson create-followup-template not found in module 3';
    RETURN;
  END IF;
  
  -- Delete existing quizzes to avoid duplicates
  DELETE FROM public.lesson_quizzes WHERE lesson_id = v_lesson_id;


  -- Question 1
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What is the primary goal of a follow-up email?', 
    '["To tell your entire company history","To thank them, remind them why they connected, and invite one next step","To ask for multiple things at once","To send as many emails as possible"]'::jsonb,
    'To thank them, remind them why they connected, and invite one next step',
    'Follow-up emails should be focused: thank the person, remind them of the context, and give them one clear next step to take.', 
    1
  )
  RETURNING id INTO v_quiz_id;


  -- Question 2
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'Why should you save follow-up emails as templates?', 
    '["They are required by law","You will send this type of email repeatedly","Templates send automatically","They cost less to send"]'::jsonb,
    'You will send this type of email repeatedly',
    'Follow-up situations happen repeatedly in business. Having a template saves time and ensures consistency in your messaging.', 
    2
  )
  RETURNING id INTO v_quiz_id;


  -- Question 3
  INSERT INTO public.lesson_quizzes (lesson_id, question, options, correct_answer, explanation, sort_order)
  VALUES (
    v_lesson_id, 
    'What should you always do before saving a follow-up template?', 
    '["Share it on social media","Send yourself a test email to verify everything works","Ask your competitors to review it","Print a physical copy"]'::jsonb,
    'Send yourself a test email to verify everything works',
    'Always test your template by sending it to yourself. Check that links work, personalization renders correctly, and the formatting looks good.', 
    3
  )
  RETURNING id INTO v_quiz_id;

END $$;
